CREATE TABLE ow_schema_migrations (version INTEGER PRIMARY KEY, applied_at_utc TEXT NOT NULL);
CREATE TABLE ow_identities (id TEXT PRIMARY KEY, role TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE ow_sessions (session_hash TEXT PRIMARY KEY, csrf_hash TEXT NOT NULL, subject_id TEXT NOT NULL, expires_ms INTEGER NOT NULL);
CREATE TABLE ow_profiles (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL, version TEXT NOT NULL, content_hash TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE ow_strategies (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES ow_profiles(id), revision INTEGER NOT NULL, baseline_hash TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE ow_instances (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), payload_json TEXT NOT NULL);
CREATE TABLE ow_datasets (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), revision INTEGER NOT NULL, content_hash TEXT NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE ow_runs (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), instance_id TEXT NOT NULL REFERENCES ow_instances(id), revision INTEGER NOT NULL, state TEXT NOT NULL, context_json TEXT NOT NULL);
CREATE UNIQUE INDEX ow_instance_reservation ON ow_runs(instance_id) WHERE state IN ('READY', 'ACTIVE', 'COMPLETING');
CREATE TRIGGER ow_run_context_no_update BEFORE UPDATE OF id,strategy_id,instance_id,context_json ON ow_runs BEGIN SELECT RAISE(ABORT,'immutable run context'); END;
CREATE TABLE ow_cases (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), instance_id TEXT NOT NULL REFERENCES ow_instances(id), run_id TEXT NOT NULL REFERENCES ow_runs(id), revision INTEGER NOT NULL, stage TEXT NOT NULL, work_status TEXT NOT NULL, baseline_hash TEXT NOT NULL, candidate_hash TEXT, owner_id TEXT NOT NULL, waiting_on TEXT, payload_json TEXT NOT NULL);
CREATE TABLE ow_tasks (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES ow_cases(id), kind TEXT NOT NULL, status TEXT NOT NULL, artifact_id TEXT REFERENCES ow_artifacts(id), required INTEGER NOT NULL DEFAULT 1, UNIQUE(case_id,kind));
CREATE TABLE ow_artifacts (id TEXT PRIMARY KEY, strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), run_id TEXT NOT NULL REFERENCES ow_runs(id), case_id TEXT REFERENCES ow_cases(id), producer_id TEXT NOT NULL, recipient_id TEXT NOT NULL, kind TEXT NOT NULL, candidate_hash TEXT, baseline_hash TEXT NOT NULL, dependencies_json TEXT NOT NULL, manifest_json TEXT NOT NULL, content BLOB NOT NULL);
CREATE TABLE ow_approval_requests (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES ow_cases(id), gate TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES ow_artifacts(id), snapshot_hash TEXT NOT NULL, baseline_hash TEXT NOT NULL, candidate_hash TEXT, recipient_id TEXT NOT NULL, tests_json TEXT NOT NULL, scope TEXT NOT NULL, revision INTEGER NOT NULL, state TEXT NOT NULL, expires_at_utc TEXT NOT NULL, request_hash TEXT NOT NULL, snapshot_json TEXT NOT NULL);
CREATE TRIGGER ow_approval_snapshot_no_update BEFORE UPDATE OF id,case_id,gate,artifact_id,snapshot_hash,baseline_hash,candidate_hash,recipient_id,tests_json,scope,expires_at_utc,request_hash,snapshot_json ON ow_approval_requests BEGIN SELECT RAISE(ABORT,'immutable approval snapshot'); END;
CREATE TRIGGER ow_approval_snapshot_no_delete BEFORE DELETE ON ow_approval_requests BEGIN SELECT RAISE(ABORT,'immutable approval snapshot'); END;
CREATE TABLE ow_decisions (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE REFERENCES ow_approval_requests(id), case_id TEXT NOT NULL REFERENCES ow_cases(id), binding_json TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE ow_decision_revocations (decision_id TEXT PRIMARY KEY REFERENCES ow_decisions(id), reason TEXT NOT NULL, revoked_at_utc TEXT NOT NULL, actor_id TEXT NOT NULL);
CREATE TABLE ow_handoffs (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES ow_cases(id), artifact_id TEXT NOT NULL REFERENCES ow_artifacts(id), decision_id TEXT NOT NULL REFERENCES ow_decisions(id), recipient_id TEXT NOT NULL, revision INTEGER NOT NULL, state TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TRIGGER ow_handoff_instruction_no_update BEFORE UPDATE OF payload_json ON ow_handoffs WHEN json_extract(OLD.payload_json,'$.instruction_md') IS NOT json_extract(NEW.payload_json,'$.instruction_md') OR json_extract(OLD.payload_json,'$.instruction_hash') IS NOT json_extract(NEW.payload_json,'$.instruction_hash') BEGIN SELECT RAISE(ABORT,'immutable approved instruction'); END;
CREATE TABLE ow_events (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_id TEXT NOT NULL, action TEXT NOT NULL, actor_id TEXT NOT NULL, actor_role TEXT NOT NULL, created_at_utc TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE ow_outbox (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES ow_cases(id), recipient_id TEXT NOT NULL REFERENCES ow_identities(id), payload_hash TEXT NOT NULL, payload_json TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_ms INTEGER NOT NULL, lease_id TEXT, lease_until_ms INTEGER, last_error TEXT);
CREATE TABLE ow_inbox (producer_id TEXT NOT NULL, message_id TEXT NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(producer_id,message_id));
CREATE TABLE ow_quarantine (id INTEGER PRIMARY KEY AUTOINCREMENT, producer_id TEXT NOT NULL, message_id TEXT NOT NULL, reason TEXT NOT NULL, payload_hash TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE ow_health (id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES ow_identities(id), strategy_id TEXT NOT NULL REFERENCES ow_strategies(id), instance_id TEXT NOT NULL REFERENCES ow_instances(id), payload_json TEXT NOT NULL, UNIQUE(provider_id,instance_id));
CREATE TABLE ow_blockers (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES ow_cases(id), owner_id TEXT NOT NULL, action TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE ow_setup_receipts (id TEXT PRIMARY KEY, content_hash TEXT NOT NULL, payload_json TEXT NOT NULL, classification TEXT NOT NULL CHECK(classification='HISTORICAL_SETUP_NOT_APPROVAL'));
INSERT INTO ow_schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
